def travel_time(distance, u, v, direction):
    speed = u + v if direction == 'down' else u - v
    if speed <= 0:
        return None  # cannot move upstream
    return distance / speed
# Example: travel_time(28, 10, 4, 'down') returns 2.0

def can_go_upstream(u, v):
    return u > v
# can_go_upstream(5,6) -> False
